def add(a, b):
    return a + b
print(add(3, 5))

def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)
print(factorial(5))

class Dog:
    def __init__(self, name):
        self.name = name
    def bark(self):
        return f'{self.name} says woof!'
d = Dog('Rex')
print(d.bark())

