def is_palindrome(s):
    return s == s[::-1]
print(is_palindrome('racecar'))

try:
    result = 10 / 0
except ZeroDivisionError:
    print('Cannot divide by zero')

def fibonacci(n):
    a, b = 0, 1
    for _ in range(n):
        yield a
        a, b = b, a + b
print(list(fibonacci(8)))

counts = {}
words = ['cat', 'dog', 'cat', 'bird', 'dog', 'cat']
for w in words:
    counts[w] = counts.get(w, 0) + 1
print(counts)

