def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr
print(bubble_sort([64, 34, 25, 12]))

def greet_all(*names):
    for name in names:
        print(f'Hi, {name}!')
greet_all('Alice', 'Bob', 'Charlie')

class Animal:
    def __init__(self, name):
        self.name = name
    def speak(self):
        raise NotImplementedError

class Cat(Animal):
    def speak(self):
        return f'{self.name} says meow'

c = Cat('Whiskers')
print(c.speak())
